#include "Aevrynd/ReplicationProtocol3D.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <cstring>
#include <limits>
#include <type_traits>

namespace Aevrynd {namespace {
constexpr std::uint32_t Magic=0x504e4541u; // AENP 小端序標記。
struct Writer {std::vector<std::byte>& b;std::size_t limit;bool ok{true};
 template<class T>void U(T value){using V=std::make_unsigned_t<T>;if(!ok||sizeof(T)>limit-b.size()){ok=false;return;}V v=static_cast<V>(value);for(std::size_t i=0;i<sizeof(T);++i)b.push_back(std::byte((v>>(i*8))&0xff));}
 void Raw(std::span<const std::byte> value){if(!ok||value.size()>limit-b.size()){ok=false;return;}b.insert(b.end(),value.begin(),value.end());}
};
struct Reader {std::span<const std::byte> b;std::size_t p{};bool ok{true};
 template<class T>T U(){using V=std::make_unsigned_t<T>;if(!ok||sizeof(T)>b.size()-p){ok=false;return{};}V v{};for(std::size_t i=0;i<sizeof(T);++i)v|=V(std::to_integer<unsigned>(b[p++]))<<(i*8);return static_cast<T>(v);}
 std::span<const std::byte> Raw(std::size_t n){if(!ok||n>b.size()-p){ok=false;return{};}auto r=b.subspan(p,n);p+=n;return r;}
};
void Id(Writer&w,NetworkEntityId3D v){w.U(v.high);w.U(v.low);}NetworkEntityId3D Id(Reader&r){return{r.U<std::uint64_t>(),r.U<std::uint64_t>()};}
void Stable(Writer&w,StableObjectId3D v){w.U(v.high);w.U(v.low);}StableObjectId3D Stable(Reader&r){return{r.U<std::uint64_t>(),r.U<std::uint64_t>()};}
bool Position(Writer&w,GlobalPosition3D v){if(!NormalizeGlobalPosition3D(v)||!std::isfinite(v.offset.x)||!std::isfinite(v.offset.y)||!std::isfinite(v.offset.z))return false;w.U(v.chunk.x);w.U(v.chunk.y);w.U(v.chunk.z);for(float f:{v.offset.x,v.offset.y,v.offset.z}){const double q=std::round(double(f)*1000.0);if(q<(std::numeric_limits<std::int32_t>::min)()||q>(std::numeric_limits<std::int32_t>::max)())return false;w.U(std::int32_t(q));}return w.ok;}
bool Position(Reader&r,GlobalPosition3D&v){v.chunk={r.U<std::int64_t>(),r.U<std::int64_t>(),r.U<std::int64_t>()};v.offset={float(r.U<std::int32_t>())/1000.f,float(r.U<std::int32_t>())/1000.f,float(r.U<std::int32_t>())/1000.f};return r.ok&&NormalizeGlobalPosition3D(v);}
void Float(Writer&w,float v){w.U(std::bit_cast<std::uint32_t>(v));}bool Float(Reader&r,float&v){v=std::bit_cast<float>(r.U<std::uint32_t>());return r.ok&&std::isfinite(v);}
ReplicationMessageType3D Type(const ReplicationMessage3D&m){return std::visit([](const auto&v){using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,ReplicationHandshake3D>)return ReplicationMessageType3D::Handshake;else if constexpr(std::is_same_v<T,ReplicationInputCommand3D>)return ReplicationMessageType3D::InputCommand;else if constexpr(std::is_same_v<T,ReplicationSnapshot3D>)return ReplicationMessageType3D::Snapshot;else if constexpr(std::is_same_v<T,ReplicationAck3D>)return ReplicationMessageType3D::Ack;else if constexpr(std::is_same_v<T,ReplicationMutationRequest3D>)return ReplicationMessageType3D::MutationRequest;else return ReplicationMessageType3D::MutationReceipt;},m);}
bool Payload(const ReplicationMessage3D&m,std::vector<std::byte>&out,ReplicationCodecLimits3D l){Writer w{out,l.maximumPacketBytes};return std::visit([&](const auto&v)->bool{using T=std::decay_t<decltype(v)>;
 if constexpr(std::is_same_v<T,ReplicationHandshake3D>){if(!v.sessionEpoch||!v.clientId||v.protocolVersion!=ReplicationProtocolVersion3D)return false;w.U(v.sessionEpoch);w.U(v.clientId);w.U(v.protocolVersion);}
 else if constexpr(std::is_same_v<T,ReplicationInputCommand3D>){if(!v.sessionEpoch||!v.clientId||!v.sequence)return false;w.U(v.sessionEpoch);w.U(v.tick);w.U(v.sequence);w.U(v.clientId);w.U(v.moveX);w.U(v.moveZ);w.U(v.yaw);w.U(std::uint8_t((v.jump?1u:0u)|(v.sprint?2u:0u)));}
 else if constexpr(std::is_same_v<T,ReplicationSnapshot3D>){if(!v.sessionEpoch||!v.clientId||v.entities.size()>l.maximumEntities||v.despawned.size()>l.maximumDespawns)return false;w.U(v.sessionEpoch);w.U(v.serverTick);w.U(v.baselineTick);w.U(v.interestEpoch);w.U(v.originGeneration);w.U(v.clientId);w.U(std::uint8_t(v.full));w.U(std::uint32_t(v.entities.size()));w.U(std::uint32_t(v.despawned.size()));for(const auto&e:v.entities){if(!e.id||!std::isfinite(e.velocity.x)||!std::isfinite(e.velocity.y)||!std::isfinite(e.velocity.z))return false;Id(w,e.id);if(!Position(w,e.position))return false;Float(w,e.velocity.x);Float(w,e.velocity.y);Float(w,e.velocity.z);w.U(e.flags);}for(auto id:v.despawned){if(!id)return false;Id(w,id);}}
 else if constexpr(std::is_same_v<T,ReplicationAck3D>){if(!v.sessionEpoch||!v.clientId)return false;w.U(v.sessionEpoch);w.U(v.snapshotTick);w.U(v.inputTick);w.U(v.clientId);}
 else if constexpr(std::is_same_v<T,ReplicationMutationRequest3D>){if(!v.sessionEpoch||!v.clientId||!v.clientRequestId)return false;w.U(v.sessionEpoch);w.U(v.clientRequestId);w.U(v.clientId);WorldChunkDeltaSnapshot3D s{};s.key=v.key;s.base={};s.lastSequence=v.operation.sequence;s.operations.push_back(v.operation);std::vector<std::byte>x;if(!EncodeWorldChunkDeltaSnapshot3D(s,x,l.maximumMutationBytes))return false;w.U(std::uint32_t(x.size()));w.Raw(x);}
 else {if(!v.sessionEpoch||!v.clientId||!v.clientRequestId)return false;w.U(v.sessionEpoch);w.U(v.clientRequestId);w.U(v.serverTick);w.U(v.sequence);w.U(v.clientId);w.U(std::uint8_t(v.accepted));w.U(std::uint8_t(v.durable));Stable(w,v.operationId);}return w.ok;},m);}
}
bool EncodeReplicationPacket3D(const ReplicationMessage3D&m,std::vector<std::byte>&bytes,ReplicationPacketReceipt3D*receipt,ReplicationCodecLimits3D l){bytes.clear();constexpr std::size_t HeaderBytes=48;if(l.maximumPacketBytes<HeaderBytes||l.maximumPacketBytes>MaximumReplicationPacketBytes3D)return false;std::vector<std::byte> p;if(!Payload(m,p,l)||p.size()>l.maximumPacketBytes-HeaderBytes)return false;std::array<std::byte,32> payloadSha{};if(!WorldDeltaSha2563D(p,payloadSha))return false;Writer w{bytes,l.maximumPacketBytes};w.U(Magic);w.U(ReplicationProtocolVersion3D);w.U(std::uint8_t(Type(m)));w.U(std::uint8_t(0));w.U(std::uint32_t(p.size()));const auto crc=WorldDeltaCrc32C3D(p);w.U(crc);w.Raw(payloadSha);w.Raw(p);if(!w.ok)return false;std::array<std::byte,32> sha{};if(!WorldDeltaSha2563D(bytes,sha)){bytes.clear();return false;}if(receipt)*receipt={Type(m),ReplicationProtocolVersion3D,sha,crc};return true;}
bool DecodeReplicationPacket3D(std::span<const std::byte>bytes,ReplicationMessage3D&m,ReplicationPacketReceipt3D*receipt,ReplicationCodecLimits3D l){constexpr std::size_t HeaderBytes=48;if(bytes.size()<HeaderBytes||bytes.size()>l.maximumPacketBytes||l.maximumPacketBytes>MaximumReplicationPacketBytes3D)return false;Reader h{bytes};if(h.U<std::uint32_t>()!=Magic||h.U<std::uint16_t>()!=ReplicationProtocolVersion3D)return false;const auto type=ReplicationMessageType3D(h.U<std::uint8_t>());if(h.U<std::uint8_t>()!=0)return false;const auto n=h.U<std::uint32_t>(),crc=h.U<std::uint32_t>();const auto expectedSha=h.Raw(32);if(!h.ok||n!=bytes.size()-HeaderBytes)return false;const auto payload=bytes.subspan(HeaderBytes);std::array<std::byte,32> payloadSha{};if(WorldDeltaCrc32C3D(payload)!=crc||!WorldDeltaSha2563D(payload,payloadSha)||!std::ranges::equal(expectedSha,payloadSha))return false;Reader r{payload};
 switch(type){case ReplicationMessageType3D::Handshake:{ReplicationHandshake3D v{r.U<std::uint64_t>(),r.U<std::uint32_t>(),r.U<std::uint16_t>()};if(!v.sessionEpoch||!v.clientId||v.protocolVersion!=ReplicationProtocolVersion3D)return false;m=v;break;}case ReplicationMessageType3D::InputCommand:{ReplicationInputCommand3D v{};v.sessionEpoch=r.U<std::uint64_t>();v.tick=r.U<std::uint64_t>();v.sequence=r.U<std::uint64_t>();v.clientId=r.U<std::uint32_t>();v.moveX=r.U<std::int16_t>();v.moveZ=r.U<std::int16_t>();v.yaw=r.U<std::int16_t>();const auto controls=r.U<std::uint8_t>();if((controls&~3u)||!v.sessionEpoch||!v.clientId||!v.sequence)return false;v.jump=(controls&1u)!=0;v.sprint=(controls&2u)!=0;m=v;break;}case ReplicationMessageType3D::Snapshot:{ReplicationSnapshot3D v{};v.sessionEpoch=r.U<std::uint64_t>();v.serverTick=r.U<std::uint64_t>();v.baselineTick=r.U<std::uint64_t>();v.interestEpoch=r.U<std::uint64_t>();v.originGeneration=r.U<std::uint64_t>();v.clientId=r.U<std::uint32_t>();const auto full=r.U<std::uint8_t>();const auto ec=r.U<std::uint32_t>();const auto dc=r.U<std::uint32_t>();if(full>1||ec>l.maximumEntities||dc>l.maximumDespawns||!v.sessionEpoch||!v.clientId)return false;v.full=full!=0;v.entities.resize(ec);v.despawned.resize(dc);for(auto&e:v.entities){e.id=Id(r);if(!e.id||!Position(r,e.position)||!Float(r,e.velocity.x)||!Float(r,e.velocity.y)||!Float(r,e.velocity.z))return false;e.flags=r.U<std::uint32_t>();}for(auto&id:v.despawned){id=Id(r);if(!id)return false;}m=std::move(v);break;}case ReplicationMessageType3D::Ack:{ReplicationAck3D v{r.U<std::uint64_t>(),r.U<std::uint64_t>(),r.U<std::uint64_t>(),r.U<std::uint32_t>()};if(!v.sessionEpoch||!v.clientId)return false;m=v;break;}case ReplicationMessageType3D::MutationRequest:{ReplicationMutationRequest3D v{};v.sessionEpoch=r.U<std::uint64_t>();v.clientRequestId=r.U<std::uint64_t>();v.clientId=r.U<std::uint32_t>();const auto size=r.U<std::uint32_t>();if(!v.sessionEpoch||!v.clientId||!v.clientRequestId||size>l.maximumMutationBytes)return false;WorldChunkDeltaSnapshot3D s;if(!DecodeWorldChunkDeltaSnapshot3D(r.Raw(size),s,l.maximumMutationBytes)||s.operations.size()!=1)return false;v.key=s.key;v.operation=s.operations.front();m=std::move(v);break;}case ReplicationMessageType3D::MutationReceipt:{ReplicationMutationReceipt3D v{};v.sessionEpoch=r.U<std::uint64_t>();v.clientRequestId=r.U<std::uint64_t>();v.serverTick=r.U<std::uint64_t>();v.sequence=r.U<std::uint64_t>();v.clientId=r.U<std::uint32_t>();const auto a=r.U<std::uint8_t>();const auto d=r.U<std::uint8_t>();v.operationId=Stable(r);if(a>1||d>1||!v.sessionEpoch||!v.clientId||!v.clientRequestId)return false;v.accepted=a!=0;v.durable=d!=0;m=v;break;}default:return false;}
 if(!r.ok||r.p!=r.b.size())return false;std::array<std::byte,32>sha{};if(!WorldDeltaSha2563D(bytes,sha))return false;if(receipt)*receipt={type,ReplicationProtocolVersion3D,sha,crc};return true;}
}
